SELECT ws.id as scheduleId, ws.live_room_id as liveRoomId, lr.anchor_number as secUid, lr.platform as platformType, ws.work_day as workDay, ws.start_work as startWork, ws.end_work as endWork, ws.schedule_duration as scheduleDuration, ws.rest_duration as restDuration, se.employee_id as employeeId, e.name as employeeName, se.position_id as positionId, se.id as scheduleEmployeeId FROM work_schedule ws JOIN live_room lr ON ws.live_room_id = lr.id AND lr.is_deleted = 0 JOIN schedule_employee se ON ws.id = se.schedule_id AND se.is_deleted = 0 LEFT JOIN employee e ON se.employee_id = e.id AND e.is_deleted = 0 WHERE ws.tenant_id = #{tenantId} AND ws.is_deleted = 0
and se.id < #{idx}
AND lr.platform = #{platformType}
AND lr.sec_uid IN
#{secUid}
AND ws.work_day > #{minDate}
AND ws.work_day < #{maxDate}
AND se.position_id IN
#{posId}
order by se.id desc limit #{limit}

SELECT ws.id, lr.platform as platformType, lr.anchor_number as secUid, ws.live_room_id, ws.work_day as workDay, ws.start_work, ws.end_work, ws.schedule_duration FROM live_room lr JOIN work_schedule ws ON ws.live_room_id = lr.id AND lr.is_deleted = 0 WHERE ws.tenant_id = #{tenantId}
and ws.id < #{idx}
AND ws.is_deleted = 0 AND ws.work_day = #{day} AND EXISTS ( SELECT 1 FROM schedule_employee se WHERE se.is_deleted = 0 AND se.schedule_id = ws.id AND se.position_id = #{anchorPositionId} ) order by ws.id desc limit #{limit}

SELECT ws.id, lr.platform as platformType, lr.sec_uid as secUid, ws.live_room_id, ws.work_day as workDay, ws.start_work, ws.end_work, ws.schedule_duration FROM live_room lr JOIN work_schedule ws ON ws.live_room_id = lr.id AND lr.is_deleted = 0 WHERE ws.tenant_id = #{tenantId}
and ws.id < #{idx}
AND ws.is_deleted = 0 AND ws.work_day >= #{startTime} AND ws.work_day < #{futureDay} AND EXISTS ( SELECT 1 FROM schedule_employee se WHERE se.is_deleted = 0 AND se.schedule_id = ws.id AND se.position_id = #{anchorPositionId} ) order by ws.id desc limit #{limit}

select a.id, a.live_room_id, a.work_day, a.start_work, a.end_work, a.schedule_duration, a.rest_duration, a.remark,
       b.employee_id, b.position_id, b.id as schedule_employee_id
from work_schedule as a
        join schedule_employee as b on a.id = b.schedule_id
where a.tenant_id = #{tenantId} and a.is_deleted = 0
and b.is_deleted = 0 and b.employee_id = #{employeeId}

  and a.live_room_id = #{req.liveRoomId}


  and (a.work_day >= #{req.startDate} or (a.end_work <= a.start_work and DATE_ADD(a.work_day, INTERVAL 1 DAY) >= #{req.startDate}))


  and a.work_day <= #{req.endDate}


  and a.id < #{idx}

order by a.id desc limit #{limit}

select a.id, a.live_room_id, a.work_day, a.start_work, a.end_work, a.schedule_duration, a.rest_duration, a.remark,
b.employee_id, b.position_id, b.id as schedule_employee_id
from work_schedule as a
join schedule_employee as b on a.id = b.schedule_id
where a.is_deleted = 0 and b.is_deleted = 0 and b.employee_id in

    #{employeeId}


    and a.work_day >= #{startDate}


    and a.work_day <= #{endDate}


    and a.id < #{idx}

order by a.id desc limit #{limit}
